import hashlib
import hmac
import socket
import struct
import sys

# Keep the project free of generated bytecode directories.
sys.dont_write_bytecode = True

from kyber_py.ml_kem import ML_KEM_512
from dfa_spec import DFARejection, HandshakeDFA

HOST = "127.0.0.1"
PORT = 5050
TYPES = {"PK": 1, "CT": 2, "CONF_A": 3, "CONF_B": 4}
SIZES = {"PK": 800, "CT": 768, "CONF_A": 32, "CONF_B": 32}


def send_msg(sock, symbol, payload):
    sock.sendall(struct.pack("!BH", TYPES[symbol], len(payload)) + payload)


def _recv_exact(sock, size):
    data = bytearray()
    while len(data) < size:
        chunk = sock.recv(size - len(data))
        if not chunk:
            raise ConnectionError("EOF before a complete message")
        data.extend(chunk)
    return bytes(data)


def recv_msg(sock):
    type_byte, size = struct.unpack("!BH", _recv_exact(sock, 3))
    return type_byte, _recv_exact(sock, size)


def classify(type_byte, payload):
    for symbol, tag in TYPES.items():
        if type_byte == tag and len(payload) == SIZES[symbol]:
            return symbol
    return "INVALID"


def _confirmation(secret, label):
    return hmac.new(secret, label, hashlib.sha256).digest()


def _step(dfa, party, direction, symbol):
    before = dfa.state
    try:
        dfa.step(symbol)
    finally:
        print(f"[{party}] {direction} {symbol:<7} {before} -> {dfa.state}", flush=True)


def run_client(sock):
    sock.settimeout(2)
    dfa, transcript = HandshakeDFA(), []
    _step(dfa, "A", "send", "PK")
    public_key, private_key = ML_KEM_512.keygen()
    send_msg(sock, "PK", public_key)
    transcript.append(("PK", public_key))

    type_byte, ciphertext = recv_msg(sock)
    symbol = classify(type_byte, ciphertext)
    _step(dfa, "A", "recv", symbol)
    transcript.append((symbol, ciphertext))
    _step(dfa, "A", "send", "CONF_A")
    secret = ML_KEM_512.decaps(private_key, ciphertext)
    confirmation = _confirmation(secret, b"CONF_A")
    send_msg(sock, "CONF_A", confirmation)
    transcript.append(("CONF_A", confirmation))

    type_byte, confirmation = recv_msg(sock)
    symbol = classify(type_byte, confirmation)
    _step(dfa, "A", "recv", symbol)
    if not hmac.compare_digest(confirmation, _confirmation(secret, b"CONF_B")):
        raise ValueError("MAC_FAIL: B's CONF_B did not verify")
    transcript.append((symbol, confirmation))
    assert dfa.accepted
    print(f"[A] established; secret fingerprint {hashlib.sha256(secret).hexdigest()[:16]}")
    print("[A] shared secret matches B (CONF_B verified)")
    return secret, transcript


def run_server(sock):
    sock.settimeout(2)
    dfa, symbol = HandshakeDFA(), "EOF/timeout"
    try:
        type_byte, public_key = recv_msg(sock)
        symbol = classify(type_byte, public_key)
        _step(dfa, "B", "recv", symbol)
        _step(dfa, "B", "send", "CT")
        secret, ciphertext = ML_KEM_512.encaps(public_key)
        send_msg(sock, "CT", ciphertext)

        type_byte, confirmation = recv_msg(sock)
        symbol = classify(type_byte, confirmation)
        _step(dfa, "B", "recv", symbol)
        if not hmac.compare_digest(confirmation, _confirmation(secret, b"CONF_A")):
            return dfa.state, symbol, "MAC_FAIL"
        _step(dfa, "B", "send", "CONF_B")
        send_msg(sock, "CONF_B", _confirmation(secret, b"CONF_B"))

        # Peek distinguishes an idle/closed peer from a truncated extra frame.
        sock.settimeout(1)
        try:
            stray = sock.recv(1, socket.MSG_PEEK)
        except socket.timeout:
            stray = b""
        if stray:
            sock.settimeout(2)
            try:
                type_byte, payload = recv_msg(sock)
                symbol = classify(type_byte, payload)
            except (ConnectionError, socket.timeout):
                symbol = "INVALID"
            _step(dfa, "B", "recv", symbol)
        assert dfa.accepted
        print(f"[B] established; secret fingerprint {hashlib.sha256(secret).hexdigest()[:16]}")
        return dfa.state, "CONF_B", "ESTABLISHED"
    except DFARejection as error:
        return error.previous_state, error.symbol, "DFA_REJECT"
    except (OSError, ConnectionError) as error:
        print(f"[B] session ended: {error}", flush=True)
        return dfa.state, "EOF/timeout", "INCOMPLETE"
    except ValueError as error:
        # A shape-correct key can still fail ML-KEM's encoding checks.
        print(f"[B] invalid ML-KEM content: {error}", flush=True)
        return dfa.state, symbol, "INCOMPLETE"


def serve(port, results_queue=None):
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as listener:
        listener.settimeout(2)
        listener.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        listener.bind((HOST, port))
        listener.listen()
        print(f"[B] listening on {HOST}:{port}", flush=True)
        while True:
            try:
                sock, _ = listener.accept()
            except socket.timeout:
                continue
            with sock:
                outcome = run_server(sock)
            print(f"[B] {outcome[2]} at {outcome[0]} ({outcome[1]})", flush=True)
            if results_queue is not None:
                results_queue.put(outcome)


if __name__ == "__main__":
    mode = sys.argv[1] if len(sys.argv) == 2 else ""
    try:
        if mode == "server":
            serve(PORT)
        elif mode == "client":
            with socket.create_connection((HOST, PORT), timeout=2) as connection:
                run_client(connection)
        else:
            sys.exit("Usage: python handshake.py server|client")
    except KeyboardInterrupt:
        pass
    except (OSError, DFARejection, ValueError) as error:
        sys.exit(f"Handshake failed: {error}")
